import{_ as e,o as n,c as o,a6 as r}from"./chunks/framework.BrkgobfX.js";const u=JSON.parse('{"title":"从 LLM 到 Coding Agent","description":"逐层拆解一个生产级 Coding Agent 在裸 LLM API 之上做的每一件事。","frontmatter":{"title":"从 LLM 到 Coding Agent","description":"逐层拆解一个生产级 Coding Agent 在裸 LLM API 之上做的每一件事。","source":"https://daiw.org/manual/llm-to-agent"},"headers":[],"relativePath":"manual/agent/llm-to-agent/index.md","filePath":"manual/agent/llm-to-agent/index.md"}'),a={name:"manual/agent/llm-to-agent/index.md"};function l(i,t,g,s,d,p){return n(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="从-llm-到-coding-agent" tabindex="-1">从 LLM 到 Coding Agent <a class="header-anchor" href="#从-llm-到-coding-agent" aria-label="Permalink to &quot;从 LLM 到 Coding Agent&quot;">​</a></h1><blockquote><p>内容来源：<a href="https://daiw.org/manual/llm-to-agent" target="_blank" rel="noreferrer">daiw.org</a> · 作者 David · 原文更新于 2026-11-06</p></blockquote><blockquote><p>逐层拆解一个生产级 Coding Agent 在裸 LLM API 之上做的每一件事。</p></blockquote><h2 id="序-·-llm-只是块芯片-agent-才是整台机器" tabindex="-1">序 · LLM 只是块芯片，Agent 才是整台机器 <a class="header-anchor" href="#序-·-llm-只是块芯片-agent-才是整台机器" aria-label="Permalink to &quot;序 · LLM 只是块芯片，Agent 才是整台机器&quot;">​</a></h2><p>现在人人都在用 Coding Agent：你说一句“帮我把这个 bug 修了”，它自己去读文件、搜代码、改几处、跑测试、看报错、再改，最后告诉你搞定了。整个过程像有个真人在你的终端里干活。</p><p>但如果你去看它底层依赖的东西——<strong>一个 LLM 的 API</strong>——你会发现那玩意儿“什么都不会”：</p><ul><li>它<strong>无状态</strong>：每次调用都是一张白纸，不记得上一句你说过什么。</li><li>它<strong>没有记忆</strong>：关掉这次请求，所有上下文烟消云散。</li><li>它<strong>不能做任何事</strong>：它只会<strong>输出文本</strong>。它读不了你的文件，跑不了命令，改不了代码。它连“现在几点”都不知道。</li><li>它甚至<strong>不知道自己该停在哪</strong>：给它一段话，它就续写一段话，仅此而已。</li></ul><p>于是本专栏的核心问题只有一个：</p><blockquote><p><strong>一个只会“输出文本”的无状态函数，是怎么变成一个能自主完成复杂编程任务的 Agent 的？这中间，工程上到底做了哪些事？</strong></p></blockquote><h2 id="一块芯片和一台机器的距离" tabindex="-1">一块芯片和一台机器的距离 <a class="header-anchor" href="#一块芯片和一台机器的距离" aria-label="Permalink to &quot;一块芯片和一台机器的距离&quot;">​</a></h2><p>打个比方：LLM 就像一块 CPU。CPU 很强，但一块裸芯片什么也干不了——你没法拿一块 CPU 去打字、上网、写代码。要让它变成一台能用的电脑，你还得给它配上<strong>内存、总线、硬盘、操作系统、驱动、输入输出</strong>……</p><p>Coding Agent 之于 LLM，正是<strong>整台机器之于那块芯片</strong>。模型提供“智能”，但把智能变成“能自主干活的系统”，靠的是外面这一整圈工程：</p><ul><li>怎么让它<strong>能调用工具</strong>(读文件、跑命令)？</li><li>怎么让它<strong>自主循环</strong>，而不是问一句答一句？</li><li>怎么<strong>喂给它恰到好处的上下文</strong>，又不撑爆那有限的上下文窗口？</li><li>怎么在它<strong>跑飞、报错、被打断</strong>时优雅恢复？</li><li>怎么<strong>控制权限</strong>，不让它把你的机器搞坏？</li><li>怎么<strong>省钱省延迟</strong>，不让每次对话烧掉一杯咖啡的钱？</li></ul><p>这些问题，每一个都不在“模型”里，而在“模型外面那一圈”。<strong>这一圈，就是本专栏要逐层拆开的东西。</strong></p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>本专栏的方法论：<strong>一篇文章只解决一个问题</strong>。每篇都按「这个问题的背景 → 解决方案的思路 → 落到代码的实现细节」三段式展开，力求把每个技术点揉碎讲透。我们会从“一次最朴素的 API 调用”出发，每加一篇，就往这块裸芯片上焊一个部件，直到最后拼出一台完整的机器。</p></div><h2 id="路线图" tabindex="-1">路线图 <a class="header-anchor" href="#路线图" aria-label="Permalink to &quot;路线图&quot;">​</a></h2><p>专栏按“从裸 API 逐步长成完整 Agent”的顺序推进，大致分七个阶段：</p><p><strong>第一阶段 · 起点</strong> —— 先看清我们手里到底有什么。</p><ul><li>一次 LLM API 调用到底给了你什么，又没给你什么。</li></ul><p><strong>第二阶段 · 让模型能做事</strong> —— 从“输出文本”到“能操作世界”。</p><ul><li>工具调用(function calling)：让模型开口说“我要调用哪个工具”。</li><li><strong>Agent Loop</strong>：把一次性问答变成一场自主循环——这是“Agent”这个词真正的分水岭。</li><li>工具系统的抽象设计：一个可扩展、类型安全、自带权限的工具到底长什么样。</li></ul><p><strong>第三阶段 · 流式与并发</strong> —— 让它快起来、并行起来。</p><ul><li>流式处理：边生成边解析，以及增量到达的工具参数。</li><li>边流边执行 + 并发编排：工具块一到就派发，安全的工具并行跑。</li></ul><p><strong>第四阶段 · 安全与控制</strong> —— 别让它把你机器搞坏，也别让它跑飞。</p><ul><li>权限系统：allow / deny / ask，权限模式，危险操作的闸门。</li><li>中断与转向：如何在流式中途叫停，并保持消息历史的合法性。</li><li>Hooks：在工具调用前后、回合结束时插入你自己的逻辑。</li></ul><p><strong>第五阶段 · 上下文工程</strong> —— 整个 Agent 最难、最见功力的部分。</p><ul><li>Token 预算：与有限上下文窗口的持久战。</li><li>系统提示与上下文注入：该塞什么、在哪塞、怎么塞。</li><li>Prompt 缓存：省钱省延迟的命脉，以及“字节稳定性”这条隐形红线。</li><li>自动压缩：上下文快满了，怎么把历史“折叠”成摘要还不丢关键信息。</li><li>精细化上下文管理：按需删除巨型工具结果、外置存储、内容替换。</li></ul><p><strong>第六阶段 · 健壮性</strong> —— 生产环境里，出错是常态。</p><ul><li>错误恢复与模型回退：重试、退避、降级换模型、孤儿消息清理、各类限额恢复。</li><li>成本与用量追踪：把 token 换算成钱，并实时盯住。</li><li>思考(extended thinking)的处理：签名、模型绑定，以及那些能让你调试一整天的坑。</li></ul><p><strong>第七阶段 · 扩展与规模</strong> —— 一个 Agent 打不过，就上一群。</p><ul><li>子 Agent：任务委派与上下文隔离，让主线程不被细节淹没。</li><li>MCP 与工具的懒加载：接入外部工具生态，以及几百个工具怎么按需加载。</li><li>会话历史与持久化：JSONL 落盘、断点续接、撤销。</li></ul><p><strong>实战番外 · 综合运用</strong> —— 把上面所有零件组装起来，干一件真正复杂的活。</p><ul><li>仓库总结的完整流程：一个几百万 token 的仓库塞不进窗口，Agent 是怎么建立起那张地图的。</li></ul><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p><strong>一句前置声明</strong>：本专栏聚焦<strong>通用的 Agent 工程技术</strong>——这些模式适用于任何基于 LLM 构建的 Agent。文中所有代码均为讲解而写的<strong>独立示例</strong>，用来演示技术要点本身，你可以照着在任何 LLM API 上复刻。我们只谈技术，不谈具体产品。</p></div><h2 id="配套代码-一个从零搭起的最小-agent" tabindex="-1">配套代码：一个从零搭起的最小 Agent <a class="header-anchor" href="#配套代码-一个从零搭起的最小-agent" aria-label="Permalink to &quot;配套代码：一个从零搭起的最小 Agent&quot;">​</a></h2><p>本专栏配一个<strong>可运行的开源仓库</strong> 👉 <a href="https://github.com/davidapp/coding-agent-from-scratch" target="_blank" rel="noreferrer">github.com/davidapp/coding-agent-from-scratch</a>。它不是一堆零散片段，而是<strong>一个随专栏逐篇长大的真实 Agent</strong>：每读完一篇，仓库就演进一步，加上那一篇讲的部件。你可以 <code>git checkout</code> 到任意一篇对应的版本，直接把那个阶段的 Agent 跑起来。</p><p>读到第二阶段结束，这个仓库已经是一个<strong>真能自主读写文件、跑命令、改代码</strong>的最小 Coding Agent 了——总共不过几百行。文章讲“为什么这么设计”，代码给“具体怎么落地”，两边对照着看。</p><h2 id="与生产级-agent-源码专栏对照" tabindex="-1">与生产级 Agent 源码专栏对照 <a class="header-anchor" href="#与生产级-agent-源码专栏对照" aria-label="Permalink to &quot;与生产级 Agent 源码专栏对照&quot;">​</a></h2><p>本专栏讲的是“<strong>所有 Coding Agent 共通的工程原理与最小实现</strong>”。如果你想进一步看这些部件在真实、百万行级别的生产级开源/商业 Agent 里各自怎么落地，站内还有一组配套的<strong>生产级 Agent 源码解读专栏</strong>与使用手册，强烈建议对照阅读：</p><ul><li><strong>生产级源码解读</strong>：<a href="https://daiw.org/manual/codex-source" target="_blank" rel="noreferrer">《Codex 源码解读》</a>（Rust workspace，153 个 crate）、<a href="https://daiw.org/manual/grok-build" target="_blank" rel="noreferrer">《Grok Build 源码解读》</a>、<a href="https://daiw.org/manual/kimi-code" target="_blank" rel="noreferrer">《Kimi Code 源码解读》</a>、<a href="https://daiw.org/manual/opencode" target="_blank" rel="noreferrer">《OpenCode 源码解读》</a>、<a href="https://daiw.org/manual/mimo-code" target="_blank" rel="noreferrer">《MiMo Code 源码解读》</a>、<a href="https://daiw.org/manual/minimax-code" target="_blank" rel="noreferrer">《MiniMax Code 源码解读》</a>、<a href="https://daiw.org/manual/zcode" target="_blank" rel="noreferrer">《Z Code 源码解读》</a>。</li><li><strong>命令行手册</strong>：<a href="https://daiw.org/manual/claude-code" target="_blank" rel="noreferrer">《Claude Code 中文手册》</a>、<a href="https://daiw.org/manual/codex" target="_blank" rel="noreferrer">《Codex 中文手册》</a>。</li></ul><p>教学实现让你看清骨架，生产实现让你看清骨架周围要长出多少血肉。</p><h2 id="读之前-你最好有" tabindex="-1">读之前，你最好有 <a class="header-anchor" href="#读之前-你最好有" aria-label="Permalink to &quot;读之前，你最好有&quot;">​</a></h2><ul><li>用过至少一次某个 LLM 的 API(知道 <code>messages</code>、<code>system</code>、<code>stream</code> 大概是什么)。</li><li>会读 TypeScript(示例用 TS 写，但讲的是<strong>思想</strong>，换成 Python/Go 一样成立)。</li><li>对“Agent 到底是不是黑魔法”心存好奇——读完你会发现，它一点也不魔法，全是<strong>扎实的工程</strong>。</li></ul><p>准备好了，我们从最朴素的起点开始：<a href="/Front2Full/manual/agent/llm-to-agent/raw-llm-api">一次 LLM API 调用，到底给了你什么</a>。</p>',44)])])}const h=e(a,[["render",l]]);export{u as __pageData,h as default};
